  ) AS v(iso2, year, value)
  JOIN public.countries c ON c.iso2 = v.iso2
  ON CONFLICT (country_id, indicator_id, year) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  UPDATE public.data_sync_logs
  SET status='success', finished_at=now(), rows_received=528, rows_inserted=v_inserted,
      rows_unchanged=528-v_inserted, revisions_pending=0, missing_count=273
  WHERE id=v_log_id;
END $$;

COMMIT;

-- Verification: expect 8 countries, 6 indicators, 48 combinations and values > 0.
SELECT
  (SELECT count(*) FROM public.countries) AS countries,
  (SELECT count(*) FROM public.indicators) AS indicators,
  (SELECT count(*) FROM public.indicator_values) AS indicator_values,
  (SELECT count(DISTINCT country_id::text || ':' || indicator_id) FROM public.indicator_values) AS combinations,
  (SELECT count(*) FROM public.data_sync_logs WHERE status='success') AS successful_logs,
  (SELECT count(*) FROM public.indicator_value_revision_proposals WHERE status='pending') AS pending_revisions;

SELECT indicator_id, min(year) AS first_year, max(year) AS latest_year, count(*) AS rows
FROM public.indicator_values
GROUP BY indicator_id
ORDER BY indicator_id;
